using System;
using System.Text;
using RoR2;
namespace UniversalSurvivorUnlocks
{
    // Un relato compartido: los diálogos vienen de UNA sola tabla para garantizar identidad.
    internal static class SpyBanditEncounterUSU
    {
        private static readonly string[] BanditEs = new string[] { "I. EL PRECIO DE VIAJAR GRATIS\nNunca imaginé que viajar gratis pudiera salir tan caro. Después de que descubrieran mi pequeño problema con la lista de pasajeros, la expedición decidió que debía ganarme el sustento. No me encerraron, no me abandonaron y, sobre todo, nadie me disparó. Un trato bastante generoso, si lo piensas. Me enviaron a recuperar registros de una instalación cuya señal seguía activa. Allí estaba, trabajando, cuando llegó la transmisión de Captain: habían establecido un campamento y enviaban referencias para regresar. ¡Un techo y comida! Estuve tentado de dejarlo todo y volver, pero completar mi primer encargo quizá sirviera para que dejaran de vigilarme. Además, podían quedar piezas valiosas. Encontré cajas abiertas, rastros recientes y un silencio incómodo. Entonces oí un chasquido a mi espalda.", "II. UN HOMBRE QUE NO ESTABA ALLÍ\nUn sujeto de traje impecable y rostro cubierto apareció detrás de mí, perfectamente tranquilo frente a mi escopeta. Parecía más preocupado por el polvo de su manga que por recibir un disparo. Examiné las cajas: alguien las había revisado antes de mi llegada. El desconocido me lanzó insultos con la cortesía de quien sirve té. No obstante, advertí cómo colocaba los pies, vigilaba mis manos y mantenía una vía de retirada. Era otro profesional, aunque jamás se lo habría reconocido en voz alta.", "III. DOS PROFESIONALES Y DEMASIADOS SECRETOS\nEl hombre no me dijo su nombre. Había venido por trabajo, dijo; algo se había complicado. Conozco ese tipo de historia porque he contado muchas parecidas. Protegía un dispositivo con conectores de almacenamiento y marcas parcialmente borradas. Podía ser un núcleo de datos. No sabía qué guardaba, pero valía dinero o alguien mataría por recuperarlo; quizá ambas cosas. Él notó mi interés. Yo noté que mentía con soltura. Cuando preguntó por mi comunicador y la nave, comprendí que buscaba una salida, no compañía. Una vibración interrumpió nuestro duelo de sonrisas. Entre las estructuras se abrió una grieta rojiza; una criatura enorme apareció y desapareció antes de que pudiera apuntarle.", "IV. UNA PUÑALADA BIEN COLOCADA\nEl monstruo cruzaba aquellas grietas como si el espacio fuese una puerta. Disparé para mantenerlo ocupado; el elegante desconocido se desvanecía, atacaba desde otro ángulo y regresaba a cubierto. Al principio parecía que improvisábamos. Después noté que cada aparición dejaba una señal roja, y que el hombre del traje también la estudiaba. No era el único acostumbrado a atacar desde la espalda. Comprendí su idea sin necesidad de que me la dibujara: uno distraería a la criatura y el otro aprovecharía su descuido. Preparé el siguiente movimiento.", "V. UN SOCIO QUE NO LO ADMITE\nRegresamos por los registros de mi encargo. Él comprobó discretamente que aún llevaba el núcleo y volvió a guardarlo. Lo dejé en paz: los ladrones entendemos el valor del silencio. Preguntó por naves, comunicaciones y rutas de extracción. Le conté lo justo y omití, por supuesto, cómo terminé trabajando para la expedición. El comunicado de Captain despertó su interés. Tal vez el campamento tuviera lo que buscaba. A mí me convenía un acompañante capaz de volverse invisible, y a él le convenían mis referencias de navegación. Ninguno estaba dispuesto a llamarlo amistad. Los dos, sin embargo, reconocíamos un buen trato cuando aparecía.", "VI. UN CAMINO PARA DOS DESCONOCIDOS\nEl campamento se había establecido cuando yo ya estaba en terreno. Tenía coordenadas y referencias, pero no conocía sus accesos ni los senderos. Mi compañero estudió el mapa con una desconfianza que encontraba francamente ofensiva, aunque debo admitir que algunas indicaciones eran difíciles de interpretar. Salimos de la instalación con los registros y los suministros. Captain todavía no sabía que regresaría con un desconocido de traje elegante, y yo ignoraba qué demonios guardaba ese hombre en su núcleo. Mientras caminábamos, intercambiamos una última serie de mentiras cuidadosamente seleccionadas. Él negó que fuéramos amigos; yo le recordé que ni siquiera sabía su nombre. Luego desapareció y volvió a aparecer detrás de mí, como al principio. Casi perdí el sombrero. Aquel desgraciado me mataría del susto antes que cualquier monstruo de Petrichor V. Y pensar que todavía nos quedaba todo el camino hasta el campamento." };
        private static readonly string[] BanditEn = new string[] { "I. THE PRICE OF A FREE RIDE\nI never thought traveling for free could cost so much. After my little passenger-list misunderstanding, the expedition decided I should earn my keep. They did not lock me up, abandon me, or, most importantly, shoot me. A generous arrangement, really. They sent me to retrieve records from a facility still transmitting a signal. I was working, for once, when Captain's broadcast came through: a camp had been established, with directions for returning. A roof and hot food! I considered leaving immediately, but finishing my first assignment might convince them to stop watching me. Besides, valuable equipment could be waiting. I found open crates, fresh tracks, and a particularly uncomfortable silence. Then something clicked behind me.", "II. A MAN WHO WAS NOT THERE\nA masked man in an immaculate suit materialized behind me, entirely unfazed by my shotgun. He seemed more concerned about dust on his sleeve than getting shot. I looked at the crates: somebody had searched them before I arrived. The stranger delivered insults as politely as if he were serving tea. But I noticed his footing, his attention to my hands, and his escape route. He was a professional, though I would never tell him that.", "III. TWO PROFESSIONALS AND TOO MANY SECRETS\nHe would not tell me his name. Professional business, he said; complications. I have told similar stories myself. He guarded a device with storage connectors and partly erased identification marks. A data core, perhaps. I did not know what it held, but it was worth money or worth killing for. Possibly both. He noticed my interest. I noticed how naturally he lied. His questions about my radio and our ship made one thing clear: he was looking for a way out, not for company. A tremor ended our contest of smiles. A red rift opened among the structures and an enormous creature appeared, then vanished before I could aim.", "IV. A WELL-PLACED KNIFE\nThe monster moved through those rifts as if space itself were a door. I fired to hold its attention; the fancy stranger vanished, struck from another angle, and returned to cover. At first we seemed to be improvising. Then I noticed the red marks announcing each appearance, and realized he was studying them too. I was not the only one accustomed to striking from behind. I understood his idea: one of us would distract the thing, while the other struck its exposed back. I prepared the next move.", "V. A PARTNER WHO WILL NOT ADMIT IT\nWe returned to collect the records for my assignment. He discreetly checked that he still had his core and put it away again. I left it alone: thieves know the value of silence. He asked about ships, communications, and escape routes. I told him enough, leaving out how I ended up working for the expedition. Captain's broadcast caught his attention. Perhaps the camp held what he needed. An invisible companion suited me, and he needed my navigation references. Neither was prepared to call it friendship. But we both recognized a good bargain.", "VI. A ROAD FOR TWO STRANGERS\nThe camp was established after I had already left on assignment. I had coordinates and directions, but I did not know its entrances or trails. My companion studied the map with what I considered offensive distrust, although some directions were admittedly hard to interpret. We left the facility carrying our supplies and records. Captain did not yet know I was bringing back a stranger in a fancy suit, and I did not know what was hidden in that data core. We exchanged one last set of carefully selected lies on the road. He denied that we were friends; I reminded him I did not even know his name. Then he vanished and reappeared behind me, just as he had at first. I nearly lost my hat. The bastard would scare me to death before any Petrichor V monster could. And we still had the whole road to the camp ahead of us." };
        private static readonly string[] SpyEs = new string[] { "I. UN CONTRATO PERFECTAMENTE ARRUINADO\nUn cliente me contrató para recuperar un núcleo de datos cifrados de una nave de investigación siniestrada en Petrichor V. Me infiltré entre dos equipos de recuperación rivales, adopté la identidad de un oficial de seguridad, recuperé el núcleo auténtico y dejé una copia inútil. Trabajo impecable. La extracción, por supuesto, había sido cancelada deliberadamente. Mi empleador pretendía deshacerse de mí sin pagar y había tenido la insolencia de creerme desechable. Qué vulgar. Conservé la orden de cancelación, el núcleo y las pruebas de su traición. Volví a la instalación para utilizar su señal y sus equipos de comunicaciones: necesitaba encontrar una salida. Entonces llegó un hombre armado, con sombrero y un comunicador funcional. Lo observé abrir una caja de cartón a golpes de escopeta. Parecía incapaz de guardar silencio, pero podría pertenecer a una expedición activa. Activé el camuflaje, me coloqué detrás de él y lo desactivé con un chasquido.", "II. UN PROFESIONAL, SEGÚN ÉL\nEl desconocido giró con el arma lista. Sus reflejos eran aceptables, aunque demasiado tardíos para impedir que lo sorprendieran. Hice notar las marcas que había dejado en las cajas y contemplé su manera de reaccionar a mis observaciones: se enfadaba, pero no dejaba de estudiar mis manos, mi postura ni las posibles salidas. Su método de abrir contenedores era una ofensa a la profesión; su manera de evaluar amenazas, en cambio, indicaba experiencia. Disfruté de la oportunidad de recordarle nuestra diferencia de categoría. No era completamente inútil. Simplemente parecía empeñado en demostrarlo por los medios más ruidosos.", "III. MENTIRAS ENTRE CABALLEROS\nNo le conté la verdad sobre el contrato ni la traición. El núcleo auténtico seguía en un estuche protegido. Advertí que el ladrón observaba sus conectores y las marcas borradas; probablemente sospechó que era una unidad de datos valiosa, pero no podía conocer su contenido. Lo encontré intentando guardarse una pieza de la mesa y se la hice devolver. Él reconoció mis evasivas casi tan deprisa como yo las suyas. Interesante. Cuando mencionó una expedición, le pregunté por comunicaciones y naves. Antes de obtener respuestas, una vibración atravesó la instalación. Una grieta roja anunciaba una presencia enorme. Su desplazamiento no era simple camuflaje: parecía atravesar el espacio. Mi compañero continuó bromeando. Por una vez, su ruido podía resultar útil.", "IV. UNA PUÑALADA DE EXCELENTE EJECUCIÓN\nEl adversario desaparecía y reaparecía donde surgían marcas rojizas. Su fuerza era considerable; su inteligencia, menos impresionante. Aproveché mi camuflaje para aproximarme, atacar y retirarme. El hombre de la escopeta disparaba para sostener su atención. Después dejó de protestar y comenzó a observar las grietas con atención. Había comprendido el patrón por sí mismo. Muy bien. Preparé una distracción y le indiqué que aguardara la espalda expuesta. Preparé el siguiente movimiento.", "V. UN SOCIO VERDADERAMENTE INCONVENIENTE\nComprobé el núcleo original y las credenciales que demostraban la cancelación de mi extracción. Seguían en mi poder. Mi acompañante recogió los registros solicitados por su expedición; no pregunté por el contenido de sus bolsillos y él tuvo la cortesía de no volver a mencionar el mío. Quise saber su función en la organización, pero respondió con una evasiva cuya falta de imaginación resultaba casi encantadora. Un comunicado reciente hablaba de un campamento establecido por un capitán. Allí podían existir transmisores, transporte o contactos capaces de ayudarme a abandonar el planeta. Su conocimiento de las referencias y mi capacidad de infiltración constituían un intercambio razonable. No éramos amigos. Para mi sorpresa, ambos parecíamos comprender esa distinción.", "VI. EL CAMINO HACIA UNA NUEVA OPORTUNIDAD\nMi guía no conocía el campamento: acababa de recibir sus coordenadas mientras cumplía un encargo lejos de allí. Estudié su comunicador. Las referencias eran plausibles, aunque varias resultaban difíciles de localizar desde la instalación. Él insistió en que conocía el camino; después admitió que solo conocía la dirección. Contuve una sonrisa. Salimos con sus registros y mi núcleo, cada uno guardando secretos que el otro ya sospechaba. No conocía su nombre y no tenía ninguna intención de revelar el mío antes de tiempo. Cuando me pidió explicaciones sobre qué diría en el campamento, prometí ofrecer una versión cuidadosamente seleccionada de la verdad. Caminaba delante, fastidiosamente satisfecho consigo mismo. Activé el camuflaje, cambié de posición y reaparecí detrás de él. Casi perdió el sombrero. Era una diversión infantil, desde luego; y extraordinariamente satisfactoria. Había encontrado un compañero mucho más competente de lo que indicaban sus modales, además de una posible salida. Todavía debíamos encontrar el campamento, y mi antiguo empleador seguía teniendo una deuda pendiente conmigo." };
        private static readonly string[] SpyEn = new string[] { "I. A PERFECTLY RUINED CONTRACT\nA client hired me to retrieve an encrypted data core from a research vessel wrecked on Petrichor V. I infiltrated two rival salvage teams, impersonated a security officer, retrieved the real core, and left a useless substitute. Flawless work. My extraction, naturally, had been deliberately cancelled. My employer meant to dispose of me without payment, and had the insolence to consider me expendable. How vulgar. I kept the cancellation order, the core, and proof of his betrayal. I returned to the facility to use its signal and communications equipment: I needed a way out. Then an armed man with a hat and a working radio arrived. I watched him beat a cardboard box open with his shotgun. He seemed incapable of silence, but might belong to an active expedition. I cloaked, approached from behind, and disengaged the device with a click.", "II. A PROFESSIONAL, ACCORDING TO HIM\nThe stranger turned with his weapon ready. Acceptable reflexes, though far too late to prevent my approach. I drew his attention to marks I had left on the crates and watched his reaction: he took offense, but kept examining my hands, stance, and possible exits. His method of opening containers was an insult to our profession. His assessment of threats, however, spoke of experience. I enjoyed reminding him of the difference in our standing. He was not entirely useless, merely determined to suggest otherwise by the noisiest possible means.", "III. LIES BETWEEN GENTLEMEN\nI said nothing about the contract or the betrayal. The original core remained in its protected case. I saw the thief examine its connectors and erased markings; he likely suspected that it was valuable data storage, but could not know its contents. I caught him pocketing an object and made him return it. He recognized my evasions nearly as quickly as I recognized his. Interesting. When he mentioned an expedition, I asked about ships and communications. Before he could answer, a tremor ran through the facility. A red rift heralded something enormous. It was not simple invisibility: the creature seemed to cross space. My new associate kept joking. For once, his noise could prove useful.", "IV. A BACKSTAB OF EXCELLENT EXECUTION\nThe opponent vanished and reappeared wherever red marks formed. Its strength was considerable; its intelligence rather less impressive. I used my cloak to approach, strike, and withdraw. The shotgun-wielding man held its attention with gunfire. Then he stopped protesting and began studying the rifts. He had understood the pattern on his own. Very good. I prepared a diversion and instructed him to wait for its exposed back. I prepared the next move.", "V. A MOST INCONVENIENT PARTNER\nI checked the original core and the evidence that my extraction had been cancelled. Both remained in my possession. My associate gathered the records requested by his expedition; I did not ask what he had in his pockets, and he kindly refrained from mentioning mine. I asked about his position in the organization, but he offered an evasion whose lack of imagination was almost charming. A recent broadcast spoke of a camp established by a captain. There might be transmitters, transport, or contacts there capable of getting me off the planet. His knowledge of the navigation references and my ability to infiltrate made for a reasonable exchange. We were not friends. To my surprise, we both seemed to understand the distinction.", "VI. THE ROAD TO A NEW OPPORTUNITY\nMy guide had never been to the camp: the coordinates arrived while he was away on assignment. I studied his radio. The references were credible, though several were difficult to identify from the facility. He insisted he knew the way, then admitted he only knew the direction. I suppressed a smile. We left with his records and my core, each guarding secrets the other already suspected. I did not know his name, nor did I intend to reveal mine prematurely. When he asked what I would say at the camp, I promised a carefully selected version of the truth. He walked ahead, offensively pleased with himself. I activated my cloak, moved position, and reappeared behind him. He nearly lost his hat. Childish entertainment, certainly; and thoroughly satisfying. I had found a far more competent companion than his manners suggested, along with a possible way out. We still had to find the camp, and my former employer still owed me a debt." };
        private static readonly string[][] DialogEs = new string[][] {
            new string[] { "SPY: «Right behind you.»", "BANDIT: «¡¿De dónde demonios saliste?!»", "SPY: «De detrás de ti. Creí haber sido suficientemente claro.»", "BANDIT: «¡Muy gracioso! ¿Siempre te presentas así?»", "SPY: «Solo cuando encuentro a alguien tan distraído.»", "BANDIT: «¡Eh! Estaba revisando la zona.»", "SPY: «Por supuesto. Aunque deberías comprobar mejor quién la revisó antes que tú.»", "BANDIT: «¿Y tú quién eres? ¿El encargado de mantenimiento?»", "SPY: «Un profesional.»", "BANDIT: «¡Qué coincidencia! ¡Yo también!»", "SPY: «¿De verdad? Qué tragedia para nuestra profesión.»", "BANDIT: «¡Oye! ¿Qué se supone que significa eso?»", "SPY: «Que mi definición de profesional no incluye intentar abrir una caja con la culata de una escopeta.»", "BANDIT: «¡Funcionó!»", "SPY: «La caja era de cartón.»", "BANDIT: «¡Detalles!»", "SPY: «Ah, los detalles. Precisamente aquello que separa un trabajo impecable de un accidente con sombrero.»" },
            new string[] { "BANDIT: «¿Y qué clase de profesional trabaja solo en un lugar como este?»", "SPY: «Uno que aprecia la discreción.»", "BANDIT: «También podrías decirme que buscas algo valioso. No voy a juzgarte.»", "SPY: «Qué alivio. Temía perder el respeto de un hombre que registra bolsillos ajenos.»", "BANDIT: «¡Eso es una acusación bastante seria!»", "SPY: «Entonces devuelve lo que acabas de guardar.»", "BANDIT: «Solo comprobaba su peso.»", "SPY: «Naturalmente. Y yo soy un humilde empleado de mantenimiento.»", "SPY: «Tenemos compañía.»", "BANDIT: «¿Cuántos?»", "SPY: «Suficientes para que dejes de hablar.»", "BANDIT: «Empiezo a pensar que no te agrado.»", "SPY: «Tu capacidad de observación es extraordinaria.»", "BANDIT: «¡Vaya! Dos cumplidos en menos de cinco minutos. Debes de estar impresionado.»", "SPY: «No arruines el momento.»", "BANDIT: «¿Viste eso?»", "SPY: «Sí.»", "BANDIT: «¿Y tienes alguna explicación?»", "SPY: «Todavía no.»", "BANDIT: «¡Magnífico! Me encantan los expertos que no saben nada.»", "SPY: «Entonces debes disfrutar mucho de tu propia compañía.»" },
            new string[] { "BANDIT: «¡Oye! ¡Podrías avisar antes de desaparecer!»", "SPY: «Si avisara, dejaría de ser una sorpresa.»", "BANDIT: «¡No puedo seguir un plan si no me lo explicas!»", "SPY: «Pensaba que un hombre de tus talentos sabría improvisar.»", "BANDIT: «¡Improvisar es mi especialidad!»", "SPY: «Entonces deja de quejarte y demuéstralo.»", "SPY: «Cuando vuelva a aparecer, no ataques de frente.»", "BANDIT: «¿Y qué sugieres? ¿Que le pida amablemente que se dé la vuelta?»", "SPY: «Yo conseguiré distraerlo. Tú asegúrate de estar detrás.»", "BANDIT: «¡Ja! Por fin alguien que aprecia mis talentos.»", "SPY: «No he dicho eso.»", "BANDIT: «¡No hace falta! ¡Ya entendí!»" },
            new string[] { "SPY: «Magnificent!»", "BANDIT: «¡Sabía que terminarías reconociendo mi talento!»", "SPY: «You got blood on my suit.»", "BANDIT: «¡Oye! ¡Acabo de salvarnos la vida!»", "SPY: «Y yo estoy intentando decidir si la limpieza costará más que la operación.»", "BANDIT: «¡Pues pásale la factura al monstruo!»", "SPY: «Me temo que su situación financiera acaba de empeorar considerablemente.»", "BANDIT: «¡Ja! ¡Tienes sentido del humor después de todo!»", "SPY: «No te acostumbres.»", "SPY: «Debo admitir que tu ataque fue... bastante eficaz.»", "BANDIT: «¡¿Bastante?! ¡Acabo de abrirle la espalda a una cosa que desaparecía!»", "SPY: «Sí. Y lo hiciste exactamente cuando debías. Sorprendente, considerando lo ocurrido con aquella caja.»", "BANDIT: «¡Vas a seguir hablando de la caja toda la vida, verdad?!»", "SPY: «Solo hasta que hagas algo más vergonzoso.»" },
            new string[] { "SPY: «¿Y cuál es exactamente tu función en esa organización?»", "BANDIT: «Digamos que me contrataron por mis habilidades especiales.»", "SPY: «Una manera muy elegante de evitar una respuesta.»", "BANDIT: «¡Mira quién habla!»", "SPY: «Touché.»", "SPY: «Un campamento, entonces. ¿Quién está al mando?»", "BANDIT: «Un capitán. Bastante serio. Te llevarás estupendamente con él.»", "SPY: «Lo dudo.»", "BANDIT: «Vamos, amigo. Hay suministros, comunicaciones y probablemente algo decente para comer.»", "SPY: «Me interesa la información, no tu entusiasmo.»", "BANDIT: «¡Eso dicen todos al principio!»", "SPY: «¿Y por qué habrías de llevarme hasta allí?»", "BANDIT: «Porque soy un hombre generoso.»", "BANDIT: «Está bien, ¡porque tú sabes desaparecer y yo tengo las referencias del camino! ¿Contento?»", "SPY: «Mucho más convincente.»", "BANDIT: «¿Eso significa que aceptas?»", "SPY: «Significa que puedo tolerar tu compañía durante el trayecto.»", "BANDIT: «¡Excelente! Me encantan los acuerdos entre caballeros.»", "SPY: «No recuerdo haberte llamado caballero.»" },
            new string[] { "SPY: «¿Conoces el camino?»", "BANDIT: «¡Por supuesto!»", "BANDIT: «Bueno... conozco la dirección.»", "SPY: «Una distinción bastante importante.»", "BANDIT: «¡Oye! Es un planeta enorme. No esperes que recuerde cada roca.»", "SPY: «Me conformaría con que recordaras alguna.»", "BANDIT: «¡Ja! ¿Sabes qué? Puedes quedarte aquí o acompañarme. Tu elección.»", "SPY: «Una decisión difícil. Morir abandonado en una instalación o seguir a un hombre que acaba de admitir que está perdido.»", "BANDIT: «¡No estoy perdido! ¡Todavía no hemos empezado a caminar!»", "BANDIT: «Una última pregunta. ¿Qué piensas decirles cuando quieran saber quién eres?»", "SPY: «La verdad, naturalmente.»", "SPY: «Una versión cuidadosamente seleccionada de ella.»", "BANDIT: «¡Ja! ¡Sabía que nos entenderíamos!»", "SPY: «No confundas un acuerdo temporal con una amistad.»", "BANDIT: «¡Tranquilo! ¡Ni siquiera sé tu nombre!»", "SPY: «Y, sin embargo, insistes en llamarme amigo.»", "BANDIT: «¿Preferirías que te llamara señor traje elegante?»", "SPY: «Preferiría un poco de silencio.»", "BANDIT: «¡Vaya! ¡Eso va a salirte caro!»", "SPY: «Entonces preséntame la factura.»", "BANDIT: «¡Oye! ¡¿Otra vez?!»", "SPY: «Right behind you.»" },
        };
        private static readonly string[][] DialogEn = new string[][] {
            new string[] { "SPY: “Right behind you.”", "BANDIT: “Where the hell did you come from?!”", "SPY: “From behind you. I thought I had been sufficiently clear.”", "BANDIT: “Very funny! Is that how you always introduce yourself?”", "SPY: “Only when I encounter someone so inattentive.”", "BANDIT: “Hey! I was checking the area.”", "SPY: “Of course. You should have checked who searched it before you.”", "BANDIT: “And who are you? The maintenance man?”", "SPY: “A professional.”", "BANDIT: “What a coincidence! So am I!”", "SPY: “Really? What a tragedy for our profession.”", "BANDIT: “Hey! What is that supposed to mean?”", "SPY: “My definition of professional does not include opening a box with a shotgun butt.”", "BANDIT: “It worked!”", "SPY: “The box was cardboard.”", "BANDIT: “Details!”", "SPY: “Ah, details. Precisely what separates flawless work from an accident in a hat.”" },
            new string[] { "BANDIT: “And what sort of professional works alone in a place like this?”", "SPY: “One who appreciates discretion.”", "BANDIT: “You could just say you are after something valuable. I will not judge.”", "SPY: “What a relief. I feared losing the respect of a man who searches other people’s pockets.”", "BANDIT: “That is a serious accusation!”", "SPY: “Then return what you just pocketed.”", "BANDIT: “I was only checking its weight.”", "SPY: “Naturally. And I am a humble maintenance worker.”", "SPY: “We have company.”", "BANDIT: “How many?”", "SPY: “Enough for you to stop talking.”", "BANDIT: “I am beginning to think you do not like me.”", "SPY: “Your powers of observation are extraordinary.”", "BANDIT: “Wow! Two compliments in five minutes. You must be impressed.”", "SPY: “Do not ruin the moment.”", "BANDIT: “Did you see that?”", "SPY: “Yes.”", "BANDIT: “And do you have an explanation?”", "SPY: “Not yet.”", "BANDIT: “Magnificent! I love experts who know nothing.”", "SPY: “Then you must enjoy your own company enormously.”" },
            new string[] { "BANDIT: “Hey! You could warn me before disappearing!”", "SPY: “If I warned you, it would not be a surprise.”", "BANDIT: “I cannot follow a plan unless you tell me!”", "SPY: “I thought a man of your talents could improvise.”", "BANDIT: “Improvising is my specialty!”", "SPY: “Then stop complaining and prove it.”", "SPY: “When it reappears, do not attack from the front.”", "BANDIT: “What do you suggest? Politely ask it to turn around?”", "SPY: “I will distract it. Make sure you are behind it.”", "BANDIT: “Ha! Finally someone who appreciates my talents.”", "SPY: “I did not say that.”", "BANDIT: “No need! I get it!”" },
            new string[] { "SPY: “Magnificent!”", "BANDIT: “I knew you would eventually recognize my talent!”", "SPY: “You got blood on my suit.”", "BANDIT: “Hey! I just saved our lives!”", "SPY: “And I am trying to decide whether cleaning will cost more than the operation.”", "BANDIT: “Then send the monster the bill!”", "SPY: “I fear its financial situation has deteriorated considerably.”", "BANDIT: “Ha! You do have a sense of humor!”", "SPY: “Do not get used to it.”", "SPY: “I must admit your attack was... rather effective.”", "BANDIT: “Rather?! I just stabbed a vanishing monster in the back!”", "SPY: “Yes. And your timing was exact. Surprising, considering that box.”", "BANDIT: “You are going to bring up that box forever, aren’t you?!”", "SPY: “Only until you do something more embarrassing.”" },
            new string[] { "SPY: “And what exactly is your position in that organization?”", "BANDIT: “Let us say they hired me for my special talents.”", "SPY: “A very elegant way to avoid answering.”", "BANDIT: “Look who is talking!”", "SPY: “Touché.”", "SPY: “A camp, then. Who is in charge?”", "BANDIT: “A captain. Very serious. You will get along splendidly.”", "SPY: “I doubt it.”", "BANDIT: “Come on, friend. Supplies, communications, and probably something decent to eat.”", "SPY: “I am interested in information, not your enthusiasm.”", "BANDIT: “That is what they all say at first!”", "SPY: “And why would you take me there?”", "BANDIT: “Because I am a generous man.”", "BANDIT: “Fine, because you can disappear and I have the route references! Happy?”", "SPY: “Much more convincing.”", "BANDIT: “Does that mean you accept?”", "SPY: “It means I can tolerate your company along the way.”", "BANDIT: “Excellent! I love agreements between gentlemen.”", "SPY: “I do not recall calling you a gentleman.”" },
            new string[] { "SPY: “Do you know the way?”", "BANDIT: “Of course!”", "BANDIT: “Well... I know the direction.”", "SPY: “A rather important distinction.”", "BANDIT: “Hey! This planet is huge. Do not expect me to remember every rock.”", "SPY: “I would settle for you remembering one.”", "BANDIT: “Ha! You know what? Stay here or come with me. Your choice.”", "SPY: “A difficult choice. Die in an abandoned facility or follow a man who has just admitted he is lost.”", "BANDIT: “I am not lost! We have not even started walking!”", "BANDIT: “One last question. What will you tell them when they ask who you are?”", "SPY: “The truth, naturally.”", "SPY: “A carefully selected version of it.”", "BANDIT: “Ha! I knew we would understand each other!”", "SPY: “Do not confuse a temporary agreement with friendship.”", "BANDIT: “Relax! I do not even know your name!”", "SPY: “And yet you insist on calling me friend.”", "BANDIT: “Would you prefer Mister Fancy Suit?”", "SPY: “I would prefer some silence.”", "BANDIT: “Wow! That will cost you!”", "SPY: “Then send me the invoice.”", "BANDIT: “Hey! Again?!”", "SPY: “Right behind you.”" },
        };
        internal static string GetSpy(bool es) { return Render(es ? SpyEs : SpyEn, es, true); }
        internal static string GetBandit(bool es) { return Render(es ? BanditEs : BanditEn, es, false); }
        private static string Render(string[] scenes, bool es, bool spy)
        {
            var dialogues = es ? DialogEs : DialogEn;
            var sb = new StringBuilder();
            for (int i = 0; i < scenes.Length; i++)
            {
                if (i > 0) sb.Append("\n\n");
                sb.Append(scenes[i]).Append("\n\n");
                // Escenas emparejadas: mismas intervenciones y etiquetas.
                for (int j = 0; j < dialogues[i].Length; j++)
                {
                    sb.Append(dialogues[i][j]).Append("\n");
                    if (i == 3 && j == 11) sb.Append(es ? (spy ? "Disparé desde la cobertura; el ladrón se ocultó en humo, golpeó la espalda con su Daga serrada y la criatura cayó. Me acerqué a comprobarlo." : "El desconocido disparó; aproveché mi Bomba de humo, apuñalé por la espalda a la criatura y esta cayó. Mi compañero se acercó.") : (spy ? "I fired from cover; the thief vanished in smoke, struck the back with his Serrated Dagger, and the creature fell. I stepped closer." : "He fired; I used my Smoke Bomb, stabbed the creature in the back, and it fell. My companion approached.")).Append("\n\n");
                    if (i == 5 && j == 19) sb.Append(es ? (spy ? "Activé el camuflaje y aparecí detrás de mi guía." : "El desconocido desapareció. Me giré para buscarlo.") : (spy ? "I cloaked and reappeared behind my guide." : "The stranger vanished. I turned to look for him.")).Append("\n\n");
                }
            }
            return sb.ToString().TrimEnd();
        }
    }
}
